const pageQuery = new URLSearchParams(location.search);
const requestedLanguage = pageQuery.get("lang");
const embedded = pageQuery.get("embed") === "1" && window.parent !== window;
if (embedded) document.documentElement.dataset.embedded = "true";
let lang = Object.hasOwn(STR, requestedLanguage) ? requestedLanguage : "en";
const parentOrigins = new Set(["http://127.0.0.1:8766", "http://localhost:8766"]);
const embedParentOrigin = embedded ? pageQuery.get("parentOrigin") : null;
function notifyParent(loaded) {
  if (parentOrigins.has(embedParentOrigin)) {
    parent.postMessage({type:"zhuzhen:curation-ready",language:lang,loaded},embedParentOrigin);
  }
}

function t(key) {
  const v = (STR[lang] && STR[lang][key]) ?? STR.en[key];
  return v;
}

function applyStaticLang() {
  document.getElementById("t-title").textContent = t("title");
  document.getElementById("dl-main").textContent = `${t("cmpDl")} ▾`;
  document.getElementById("compose").textContent = t("compose");
  document.getElementById("export").textContent = t(embedded ? "exportSelected" : "export");
  document.getElementById("export-gif").textContent = t("exportGif");
  gridToggle.textContent = `${t("groundGrid")} ${document.body.classList.contains("show-grid") ? "▣" : "▢"}`;
  langToggle.textContent = t("langOther");
  langToggle.hidden = embedded;
  document.title = `sprite-gen · ${t("title")}`;
  document.getElementById("sidebar-toggle").setAttribute("aria-label", lang === "zh" ? "切换文件树" : "Toggle file tree");
  const ppLabel = document.getElementById("pp-label");
  if (ppLabel) ppLabel.textContent = t("unfakeApply");
  const pxLabel = document.getElementById("pxgrid-label");
  if (pxLabel) pxLabel.textContent = t("pxGridAll") + (run.pixelUnfake && run.pixelUnfake.label ? " \u00b7 " + run.pixelUnfake.label : "");
  const pxWrap = document.getElementById("pxgrid-wrap");
  if (pxWrap) pxWrap.title = t("tPxGrid");
  const unfakeWrap = document.getElementById("unfake-wrap");
  if (unfakeWrap) unfakeWrap.title = t("tUnfakeApply");
  document.getElementById("hintbar").innerHTML = t("hints").map((h) => `<span>${h}</span>`).join("");
}

// 실시간 계약 (maintainer 확정 2026-07-14): 버튼은 '게임에 적용'이 아니다 — 지금
// 보이는 라이브 상태(프레임 캐시 + 큐레이션)를 서버가 그 자리에서 계산해
// 파일(zip)로 내려주는 다운로드다. 서버는 계산 전에 캐시를 자가치유한다.
